import{_ as r,C as d,o,c as h,j as a,a as i,E as l,a2 as n}from"./chunks/framework.B-bxTAy7.js";const u=JSON.parse('{"title":"B 站网课推荐","description":"电工学、模拟电子、数字电子、嵌入式四门课在 B 站上经得起看的公开网课清单：集数、时长、播放量与配套章节，以及怎么判断一门课值不值得看。","frontmatter":{"title":"B 站网课推荐","description":"电工学、模拟电子、数字电子、嵌入式四门课在 B 站上经得起看的公开网课清单：集数、时长、播放量与配套章节，以及怎么判断一门课值不值得看。"},"headers":[],"relativePath":"guide/courses.md","filePath":"guide/courses.md","lastUpdated":null}'),s={name:"guide/courses.md"};function b(f,t,g,p,c,m){const e=d("Meta");return o(),h("div",null,[t[0]||(t[0]=a("h1",{id:"b-站网课推荐",tabindex:"-1"},[i("B 站网课推荐 "),a("a",{class:"header-anchor",href:"#b-站网课推荐","aria-label":'Permalink to "B 站网课推荐"'},"​")],-1)),l(e,{time:"10 min",level:"指南",note:"四门课八个视频链接，都是逐条查过 B 站公开数据才写进来的"}),t[1]||(t[1]=n('<p>本站是文字笔记，演示和例题能让你自己动手，但<strong>推导过程、老师的口音与板书节奏、现场画波形的那几步</strong>，视频还是更省力。这一页把四门课对应的公开网课列出来，每条都标了体量（分 P 数、总时长）与播放量，方便你按时间预算挑。</p><p>数据由维护者在 2026-10-21 用 B 站公开接口逐条核验：分 P 数、时长、播放量都按当天的返回值原样记录，没有估、也没有凑整。</p><h2 id="结论先行-三种读法怎么配视频" tabindex="-1">结论先行：三种读法怎么配视频 <a class="header-anchor" href="#结论先行-三种读法怎么配视频" aria-label="Permalink to &quot;结论先行：三种读法怎么配视频&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你的处境</th><th>视频怎么用</th><th>主要看哪几条</th></tr></thead><tbody><tr><td><strong>时间紧</strong>（考前、临时要用）</td><td>只看单集或速成片段，不追整套</td><td>舵机那一集、单集舵机专题；考哪章搜哪章的单集</td></tr><tr><td><strong>系统学</strong>（第一次学，要能做题）</td><td>跟一套完整课，配本站章节做例题</td><td>模拟电子的国家精品版、电工学教材课、数电的 56 集</td></tr><tr><td><strong>做项目</strong>（要动手做出东西）</td><td>边做边看，缺什么补什么</td><td>江协科技 STM32 入门 + 陈加油嗯的舵机专题</td></tr></tbody></table><p>一句话：<strong>视频负责「过程」，本站负责「结论 + 动手验证」</strong>。先读本站结论建立直觉，再让视频把推导讲一遍，最后回来做例题——顺序反了，往往看完视频还是不会算。</p><h2 id="电工学-·-哈尔滨工业大学-姜三勇等《电工学》" tabindex="-1">电工学 · 哈尔滨工业大学 姜三勇等《电工学》 <a class="header-anchor" href="#电工学-·-哈尔滨工业大学-姜三勇等《电工学》" aria-label="Permalink to &quot;电工学 · 哈尔滨工业大学 姜三勇等《电工学》&quot;">​</a></h2><table tabindex="0"><thead><tr><th>课程</th><th>UP 主</th><th>体量</th><th>播放量</th><th>适合谁</th><th>配套本站章节</th></tr></thead><tbody><tr><td><a href="https://www.bilibili.com/video/BV1LdaX6tEAP" target="_blank" rel="noreferrer">电工学（上半）</a></td><td>搬运（哈工大 姜三勇等）</td><td>68 个分 P，约 46.5 小时</td><td>约 2300</td><td>要系统过一遍电路定律到三相的人</td><td><a href="./../ee/">电工学 · 课程主页</a></td></tr><tr><td><a href="https://www.bilibili.com/video/BV1QLsTzQEas" target="_blank" rel="noreferrer">电工学（下半）</a></td><td>搬运（哈工大 姜三勇等）</td><td>33 个分 P，约 21.5 小时</td><td>本次未核验</td><td>读完上半、要过磁路电机与控制的人</td><td><a href="./../ee/06-machine/magnetic">磁路与变压器</a>、<a href="./../ee/07-control/relay">继电控制</a></td></tr></tbody></table><p>上半的播放量与搬运源一样偏低，属于典型的「链接还在、内容不一定稳」的情况。<strong>搬运源不稳定，搜「哈工大 电工学 姜三勇」找最新上传</strong>，别认死某一条链接。</p><p>怎么配合本站用：先读各章「结论先行」，把 KCL/KVL、三要素法、相量这些骨架立起来，再看视频里老师一步步推；视频讲到某个例题时暂停，自己先算，再对答案。章节对应关系：直流部分配 <a href="./../ee/01-basics/kcl-kvl">01 基尔霍夫定律</a>，暂态配 <a href="./../ee/03-transient/three-factor">三要素法</a>，正弦稳态配 <a href="./../ee/04-ac/phasor">相量法</a>，三相配 <a href="./../ee/05-three-phase/circuit">三相电路</a>；下半的电机部分配 <a href="./../ee/06-machine/induction-motor">异步电动机</a>。</p><h2 id="模拟电子-·-清华大学-华成英《模拟电子技术基础》" tabindex="-1">模拟电子 · 清华大学 华成英《模拟电子技术基础》 <a class="header-anchor" href="#模拟电子-·-清华大学-华成英《模拟电子技术基础》" aria-label="Permalink to &quot;模拟电子 · 清华大学 华成英《模拟电子技术基础》&quot;">​</a></h2><table tabindex="0"><thead><tr><th>课程</th><th>UP 主</th><th>体量</th><th>播放量</th><th>适合谁</th><th>配套本站章节</th></tr></thead><tbody><tr><td><a href="https://www.bilibili.com/video/BV19s411a7KL" target="_blank" rel="noreferrer">模拟电子技术基础</a></td><td>清华 · 华成英</td><td>56 个分 P，约 41.8 小时</td><td>约 392 万</td><td>想跟最经典的一套，不在意画质</td><td><a href="./../analog/">模拟电子 · 课程主页</a></td></tr><tr><td><a href="https://www.bilibili.com/video/BV1W7411B7BQ" target="_blank" rel="noreferrer">同课高清版（国家精品）</a></td><td>清华 · 华成英</td><td>56 个分 P，约 41.8 小时</td><td>约 6.2 万</td><td>同样的课，想要看得清的板书</td><td><a href="./../analog/">模拟电子 · 课程主页</a></td></tr></tbody></table><p>第一条画质偏低（480×360），板书和特性曲线经常糊成一片；播放量高说明它是很多人第一眼找到的那版。两条内容一致，<strong>只是清晰度不同</strong>，看长视频建议直接走国家精品版。</p><p>怎么配合本站用：模电的难点不是概念而是「一张曲线图上三四个量同时动」，先在本站把 <a href="./../prereq/bjt-regions">三极管工作状态</a>、<a href="./../prereq/q-point-loadline">静态工作点与负载线</a> 这两个胶囊点开，建立「曲线 + 负载线」的图像，再去看华老师推放大倍数，你会跟得上得多。每看完一段回来做 <a href="./../analog/amplifiers">基本放大电路</a> 与 <a href="./../analog/opamp">运算放大器</a> 的例题，公式自己动手代一遍，比看视频里代一遍有用。</p><h2 id="数字电子-·-华北电力大学-童话老师-蜂考-阎石《数字电子技术基础》" tabindex="-1">数字电子 · 华北电力大学 童话老师（蜂考）阎石《数字电子技术基础》 <a class="header-anchor" href="#数字电子-·-华北电力大学-童话老师-蜂考-阎石《数字电子技术基础》" aria-label="Permalink to &quot;数字电子 · 华北电力大学 童话老师（蜂考）阎石《数字电子技术基础》&quot;">​</a></h2><table tabindex="0"><thead><tr><th>课程</th><th>UP 主</th><th>体量</th><th>播放量</th><th>适合谁</th><th>配套本站章节</th></tr></thead><tbody><tr><td><a href="https://www.bilibili.com/video/BV1CT411e7Nh" target="_blank" rel="noreferrer">数字电子技术基础</a></td><td>华北电力大学 · 童话老师（蜂考）</td><td>56 个分 P，约 34.4 小时</td><td>约 30.4 万</td><td>跟着阎石教材顺序走的人</td><td><a href="./../digital/">数字电路 · 课程主页</a></td></tr><tr><td><a href="https://www.bilibili.com/video/BV1ZHgw6wEsa" target="_blank" rel="noreferrer">配套课后题精讲</a></td><td>同系列配套（课后题版本）</td><td>54 个分 P，约 6.9 小时</td><td>本次未核验</td><td>课听懂了但课后题不会做的人</td><td><a href="./../digital/boolean-kmap">卡诺图</a>、<a href="./../digital/flip-flops">时序逻辑</a></td></tr></tbody></table><p>这套课的节奏偏讲课式：板书清楚、例题多，最后一段的课后题精讲只有 6.9 小时，是「做完作业对答案」的用法，不适合当独立课程听。</p><p>怎么配合本站用：数电最怕「听课全懂、化简全错」，所以顺序倒过来更有效——先在本站做一遍 <a href="./../digital/boolean-kmap">逻辑代数与卡诺图</a> 的交互演示，把圈组规则变成手上动作，再看视频里老师怎么处理带无关项的卡诺图；<a href="./../digital/gates">门电路</a> 与 <a href="./../digital/combinational">组合逻辑</a> 两章看完后，用课后题精讲核对解法。时序部分别只看视频，本站 <a href="./../digital/flip-flops">触发器</a> 的波形演示能让你一眼看出建立保持时间错在哪。</p><h2 id="嵌入式-·-江协科技《stm32-入门教程-2023-版》" tabindex="-1">嵌入式 · 江协科技《STM32 入门教程 2023 版》 <a class="header-anchor" href="#嵌入式-·-江协科技《stm32-入门教程-2023-版》" aria-label="Permalink to &quot;嵌入式 · 江协科技《STM32 入门教程 2023 版》&quot;">​</a></h2><table tabindex="0"><thead><tr><th>课程</th><th>UP 主</th><th>体量</th><th>播放量</th><th>适合谁</th><th>配套本站章节</th></tr></thead><tbody><tr><td><a href="https://www.bilibili.com/video/BV1th411z7sn" target="_blank" rel="noreferrer">STM32 入门教程 2023 版</a></td><td>江协科技</td><td>50 个分 P，约 33.5 小时</td><td>约 2766 万</td><td>手上有一块开发板、要真的点灯通串口的人</td><td><a href="./../embedded/">嵌入式开发 · 课程主页</a></td></tr><tr><td><a href="https://www.bilibili.com/video/BV1th411z7sn?p=16" target="_blank" rel="noreferrer">舵机那一集（P16）</a></td><td>江协科技</td><td>1 个分 P（PWM 驱动 LED 呼吸灯 / 舵机 / 直流电机），约 64 分钟</td><td>含在合集内</td><td>只差「PWM 怎么驱动执行器」这一块</td><td><a href="./../embedded/13-servo-control">13 · 舵机控制</a></td></tr><tr><td><a href="https://www.bilibili.com/video/BV15Y8NzcEkP" target="_blank" rel="noreferrer">STM32 舵机控制 PWM 驱动舵机 原理代码讲解</a></td><td>陈加油嗯</td><td>单集，约 23.5 分钟</td><td>约 3.3 万</td><td>时间只够看一集、想要完整代码流程的人</td><td><a href="./../embedded/13-servo-control">13 · 舵机控制</a></td></tr></tbody></table><p>江协这套是入门里播放量最夸张的一条，讲法是「新建工程 → 写代码 → 下载看现象」，几乎没有理论铺垫，正好和本站相反。舵机在 P16 里只占合集的一小段，主讲的还是 PWM 呼吸灯与直流电机；陈加油嗯那条 23.5 分钟的单集则把「PWM 配参 → 写 CCR → 接线供电」压缩在一条视频里，适合临时救急。</p><p>怎么配合本站用：先看本站 <a href="./../embedded/timer-pwm">定时器与 PWM</a> 弄清楚 CNT 与 CCR 到底在比什么，再跟视频配一遍参数，你会发现你比视频多知道「为什么是 PSC 71」；到舵机时，视频里的接线一旦跳过电源细节，就回来读 <a href="./../embedded/13-servo-control">13 · 舵机控制</a> 的供电与共地部分——那里讲的是视频里最常被省略、却最容易烧板的一段。</p><h2 id="使用说明与免责声明" tabindex="-1">使用说明与免责声明 <a class="header-anchor" href="#使用说明与免责声明" aria-label="Permalink to &quot;使用说明与免责声明&quot;">​</a></h2><ul><li><strong>数据核验于 2026-10-21</strong>：分 P 数、时长、播放量取自当天的 B 站公开接口返回值，<strong>播放量会变</strong>，隔几个月再来看数字对不上是正常的，以链接页面为准。</li><li><strong>搬运视频可能失效</strong>：标了「搬运」的课程随时可能被下架或删档，<strong>以 UP 主主页为准</strong>，在主页搜课程名比死守旧链接可靠。</li><li><strong>本站不隶属于任何 UP 主</strong>：这些链接只是学习路径上的参考，本站没有收到任何推荐费，也不代表对课程内容的背书；课程里的说法与本站不一致时，请以教材与你的老师为准。</li><li><strong>不保证内容永久有效</strong>：链接失效、课程被删、UP 主改名都可能发生。发现链接打不开，欢迎按 <a href="./about">关于与版权</a> 里的方式反馈。</li><li>站内章节链接不受上述影响，视频挂了笔记还在；反过来说，<strong>本站的结论与演示始终是主线，视频是补充</strong>。</li></ul><h2 id="怎么自己判断一门课值不值得看" tabindex="-1">怎么自己判断一门课值不值得看 <a class="header-anchor" href="#怎么自己判断一门课值不值得看" aria-label="Permalink to &quot;怎么自己判断一门课值不值得看&quot;">​</a></h2><p>三个五分钟就能做完的检查，比看播放量靠谱：</p><ol><li><strong>先看目录是否覆盖你的缺口</strong>：把「分 P 列表」当目录扫一遍，找你现在卡住的那几个关键词（比如「转差率」「卡诺图无关项」「PWM 互补输出」）。目录里没有，播放量再高也帮不上你；有但排在很后面，就只跳着看那几集。</li><li><strong>看前 3 集的节奏</strong>：前 3 集决定你能不能坚持。判断标准不是「讲得深不深」，而是<strong>有没有一上来就给结论、有没有随讲随写例题</strong>。如果前 3 集都在铺垫历史与定义，而你又时间紧，换一门。</li><li><strong>看有没有配套讲义、代码或习题</strong>：有讲义/课件/源码的课，你可以在视频外自己复现，学习效率通常高一档；只有嘴讲的课，看完一遍很容易什么都不剩。本站列的这几门里，江协科技有配套资料与代码，数电那套有课后题精讲，正好对应不同用法。</li></ol><p>再补一条容易忽略的：<strong>看更新与合集状态</strong>——分 P 是否齐全、有没有标「已完结」、最近有没有评论说某集失效。这些都决定你花 40 小时之后能不能把课听完。</p><h2 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to &quot;接下来&quot;">​</a></h2><ul><li>还不熟悉本站怎么用：<a href="./start">怎么用这个站</a></li><li>想知道每章写到什么程度：<a href="./status">内容状态与成熟度</a></li><li>想按依赖顺序排学习路径：<a href="./../ee/graph">知识依赖图谱</a></li></ul>',29))])}const w=r(s,[["render",b]]);export{u as __pageData,w as default};
